SELECT s.Name, s.Location
FROM stadium s
WHERE EXISTS (
    SELECT 1 FROM concert c1 WHERE c1.Stadium_ID = s.Stadium_ID AND c1.Year = '2014'
)
AND EXISTS (
    SELECT 1 FROM concert c2 WHERE c2.Stadium_ID = s.Stadium_ID AND c2.Year = '2015'
);

SELECT PetType, AVG(pet_age) as avg_age, MAX(pet_age) as max_age
FROM Pets
GROUP BY PetType;

SELECT CountryName
FROM countries
WHERE CountryId NOT IN (SELECT DISTINCT Country FROM car_makers);

SELECT DISTINCT a.Airline
FROM airlines a
WHERE EXISTS (
    SELECT 1 FROM flights f WHERE f.Airline = a.uid AND f.SourceAirport = 'CVO'
)
AND NOT EXISTS (
    SELECT 1 FROM flights f WHERE f.Airline = a.uid AND f.SourceAirport = 'APG'
);

SELECT Name, Location, District
FROM shop
ORDER BY Number_products DESC;

SELECT Name
FROM shop
WHERE Number_products > (SELECT AVG(Number_products) FROM shop);

SELECT Name
FROM employee
WHERE Employee_ID NOT IN (SELECT Employee_ID FROM evaluation);

SELECT p.first_name, p.last_name
FROM players p
WHERE p.player_id IN (
    SELECT winner_id FROM matches WHERE year = 2013
)
AND p.player_id IN (
    SELECT winner_id FROM matches WHERE year = 2016
);

SELECT c.Name
FROM country c
WHERE EXISTS (
    SELECT 1 FROM countrylanguage cl1 WHERE cl1.CountryCode = c.Code AND cl1.Language = 'English' AND cl1.IsOfficial = 'T'
)
AND EXISTS (
    SELECT 1 FROM countrylanguage cl2 WHERE cl2.CountryCode = c.Code AND cl2.Language = 'French' AND cl2.IsOfficial = 'T'
);

SELECT c.Name
FROM country c
WHERE EXISTS (
    SELECT 1 FROM countrylanguage cl1
    WHERE cl1.CountryCode = c.Code AND cl1.Language = 'English' AND cl1.IsOfficial = 'T'
)
AND EXISTS (
    SELECT 1 FROM countrylanguage cl2
    WHERE cl2.CountryCode = c.Code AND cl2.Language = 'French' AND cl2.IsOfficial = 'T'
);

SELECT SUM(c.Population) 
FROM country c
WHERE c.Code NOT IN (SELECT DISTINCT CountryCode FROM countrylanguage WHERE Language = 'English');

SELECT Record_Company FROM orchestra WHERE Year_of_Founded < 2003
INTERSECT
SELECT Record_Company FROM orchestra WHERE Year_of_Founded > 2003;

SELECT student_id FROM Friend
INTERSECT
SELECT liked_id FROM Likes;

SELECT AVG(H.grade)
FROM Highschooler H
JOIN Friend F ON H.ID = F.student_id;

SELECT state FROM Owners
INTERSECT
SELECT state FROM Professionals;

SELECT AVG(CAST(d.age AS REAL))
FROM Dogs d
WHERE EXISTS (SELECT 1 FROM Treatments WHERE Treatments.dog_id = d.dog_id);

SELECT AVG(d.age) AS average_age
FROM Dogs d
JOIN Treatments t ON d.dog_id = t.dog_id;

SELECT DISTINCT first_name
FROM (
    SELECT first_name FROM Owners
    UNION
    SELECT first_name FROM Professionals
) AS people
WHERE first_name NOT IN (
    SELECT name FROM Dogs
);

SELECT professional_id, role_code, email_address
FROM Professionals
WHERE professional_id NOT IN (SELECT professional_id FROM Treatments);

SELECT role_code, street, city, state
FROM Professionals
WHERE city LIKE '%West%';

SELECT first_name, last_name, email_address
FROM Owners
WHERE state LIKE '%North%';

SELECT first_name, last_name, email_address
FROM Owners
WHERE state LIKE '%North%';

SELECT name, age, weight
FROM Dogs
WHERE abandoned_yn = '1';

SELECT Citizenship FROM singer WHERE Birth_Year < 1945
INTERSECT
SELECT Citizenship FROM singer WHERE Birth_Year > 1955;
